def questions():
    q = {}
    for a in ["x","y","z","rx","ry","rz"]:
        q[a] = {"type":"choice","instructions":"For world axis "+a+", use the supplied axis goal_relation only. Increase means positive; decrease means negative; within_tolerance means hold. Do not infer object success.","criteria":{"negative":"goal_relation is decrease","hold":"goal_relation is within_tolerance","positive":"goal_relation is increase"}}
    q["gripper"] = {"type":"choice","instructions":"Use objective.gripper: open, close, or keep. Deliver that request; do not infer contact.","criteria":{"open":"objective requests open","close":"objective requests close","keep":"objective requests keep"}}; return q
def record(api,p,event):
    p["log"] = (p.get("log",[])+[event])[-8:]; api.checkpoint("bowl_v2",p)
def stop(api,p,why,done=False):
    record(api,p,{"result":why}); return {"completion_proposed":bool(done),"evidence":{"phase":p["phase"],"reason":why,"measurements":p["log"],"last_jaw":p.get("jaw_ack"),"partial_measurements":p.get("partial"),"limitations":"RGB-D uncertainty is heuristic; no swept-volume certificate or official success predicate."}}
def ask(api,p,text,fields,context=None,reserve=3):
    if api.state()["budgets"]["gpt_remaining"] <= reserve or api.state()["budgets"]["wall_seconds_remaining"]<30:
        record(api,p,{"gap":"review reserve reached"}); return None
    r = api.review(text,context=context,fields=fields)
    if r["measurement_errors"]:
        record(api,p,{"measurement_errors":[{"name":x["name"],"error":x["error"][:100]} for x in r["measurement_errors"][:4]]})
    if r["status"] == "stop":
        record(api,p,{"review_stop":r["explanation"][:160]}); return None
    return r
def pts(r,names):
    return [r["points"][k]["world_m"] for k in names if k in r["points"]]
def plane(points):
    if len(points)<3: return None
    try:
        f=geo.plane(points)
        if f["coefficients"][2]<=.998 or f["rms_m"]>=.004 or min(f["in_plane_spread_m"])<max(.0045,3*f["rms_m"]): return None
        return {"coefficients":np.asarray(f["coefficients"]).tolist(),"rms_m":float(f["rms_m"]),"center_world_m":np.asarray(f["center_world_m"]).tolist(),"in_plane_spread_m":np.asarray(f["in_plane_spread_m"]).tolist()}
    except (ValueError,RuntimeError): return None
def zplane(f,xy):
    n=np.asarray(f["coefficients"]); return float(-(np.dot(n[:2],xy)+n[3])/n[2])
def rim(api,p,r):
    a=pts(r,["r"+str(i) for i in range(6)])
    if len(a)<3: return None
    a=np.asarray(a); a=a[np.abs(a[:,2]-np.median(a[:,2]))<.005]; f=plane(a.tolist())
    if f is None: return None
    b=[]
    for pixel in r["parameters"]["rim_pixels"]:
        try: b.append(api.plane_point(r["parameters"]["rim_camera"],pixel,f["coefficients"])["world_m"])
        except RuntimeError: record(api,p,{"gap":"one visible rim ray failed"})
    if len(b)<4: b=a.tolist()
    if len(b)<4: return None
    try: c=geo.circle_xy(b)
    except (ValueError,RuntimeError): return None
    arc=float(2*math.pi-c["largest_angular_gap_rad"]); u=(.0015+f["rms_m"]+c["max_radial_error_m"])/max(.15,math.sin(min(math.pi,arc)/2)**2); u=float(u); center=np.asarray(c["center_xy_m"]).tolist(); radius=float(c["radius_m"]); record(api,p,{"rim_frame":r["frame_id"],"radius":radius,"uncertainty":u,"arc":arc,"plane_rms":f["rms_m"]})
    if arc<1.4 or radius<3*u or c["max_radial_error_m"]>.006: return None
    return {"c":list(center)+[zplane(f,center)],"r":radius,"u":u,"uz":.0015+f["rms_m"]+radius*math.sqrt(max(0,1-f["coefficients"][2]**2)),"frame":r["frame_id"]}
def descriptors():
    pixel={"type":"array","items":{"type":"integer","minimum":0,"maximum":767},"minItems":2,"maxItems":2}; return {"body":["same_bowl","uncertain"],"model":["upright_round_widest_rim","contradicted","unknown"],"relation":["source_support","stove_support","held","elsewhere","unknown"],"rim_camera":["agentview","robot0_eye_in_hand"],"rim_pixels":{"type":"array","items":pixel,"maxItems":8}},pixel
def outline(api,p,purpose,reserve=3):
    fields,pixel=descriptors()
    for attempt in range(2):
        r=ask(api,p,"Identify the SAME task bowl, not a screen-relative identity. "+purpose+" Return body, model and relation. Request r0..r5 on well-spaced visible yellow rim lip surfaces. rim_pixels are ONLY genuinely visible rim boundary pixels in rim_camera, never hidden inferred vertices. Use the other view / different visible arc on retry; three lip depths establish its plane and four or more boundary rays establish the circle. Do not require the complete outline.",fields,{"plan":p.get("plan"),"attempt":attempt},reserve)
        if r is not None and r["parameters"]["body"]=="same_bowl" and r["parameters"]["model"]=="upright_round_widest_rim":
            g=rim(api,p,r)
            if g is not None:
                g["relation"]=r["parameters"]["relation"]; return g
    return None
def install_ref(api,p,r):
    v=r["parameters"]; marks=pts(r,["p0","p1","p2"]); unique=v["correspondence"]=="unique" and len(marks)==3 and len(v["definitions"])==3; ref={"handle":None,"definitions":v["definitions"] if unique else [],"probes":marks if unique else [],"camera":v["patch_camera"],"polygon":v["patch_polygon"],"frame":r["frame_id"],"identity":"textured interior of the same task bowl","manual":unique}
    if len(ref["polygon"])>=3:
        try:
            h=api.track_init(ref["camera"],ref["polygon"]); ref["handle"]=h["handle"]; ref["creation"]={k:h[k] for k in ["frame_id","camera","method_number","source_sha256"]}
        except RuntimeError as e: record(api,p,{"tracker_init_error":str(e)[:160]})
    if ref["handle"] is None and not unique: return False
    ref["key"]=str(ref["handle"])+":"+str(ref["frame"]); p["ref"]=ref; record(api,p,{"reference":ref["key"],"identity":ref["identity"]}); return True
def patch_fields():
    f,pixel=descriptors(); return {"body":f["body"],"correspondence":["unique","ambiguous","unavailable"],"definitions":{"type":"array","items":{"type":"string","maxLength":160},"maxItems":3},"patch_camera":f["rim_camera"],"patch_polygon":{"type":"array","items":pixel,"maxItems":16}}
def new_ref(api,p):
    for attempt in range(2):
        r=ask(api,p,"Select a CURRENT textured interior patch of the SAME bowl, excluding hand, background and rim boundary. Return body separately from correspondence. patch_camera and patch_polygon select 3..16 visible vertices, or [] if unavailable. Request p0,p1,p2 on three identifiable noncollinear physical texture motifs, and definitions describing each persistent physical motif, not screen left/right. correspondence=unique only if those three physical identities are unambiguous; otherwise definitions=[]. A new local patch need NOT be registered to old rim landmarks. On retry use a different patch or camera.",patch_fields(),{"previous_reference":p.get("ref"),"attempt":attempt})
        if r is not None and r["parameters"]["body"]=="same_bowl" and install_ref(api,p,r):
            s=snapshot(api,p,False)
            if s is not None: return s
    return None
def snapshot(api,p,manual=True):
    ref=p.get("ref")
    if ref is None: return None
    if ref["handle"] is not None:
        try: t=api.track_update(ref["handle"])
        except RuntimeError as e:
            record(api,p,{"tracker_error":str(e)[:160]}); t={"status":"unknown"}
        if t["status"]=="tracked":
            u=float(t["rms_m"]+t["uncertainty_floor_m"]); wide=float(np.max(np.asarray(t["inlier_spread_m"]))); cloud=np.asarray(t["reference_inlier_world_m"]); sv=np.linalg.svd(cloud-cloud.mean(axis=0),compute_uv=False) if len(cloud)>=3 else np.zeros(3); spread=float(sv[1]/math.sqrt(max(1,len(cloud))))
            if t["inliers"]>=12 and t["inliers"]/max(1,t["matches"])>=.55 and u<.008 and wide>3*u:
                if not ref["probes"]:
                    a=np.asarray(t["reference_inlier_world_m"]); i=int(np.argmax(np.linalg.norm(a-a[0],axis=1))); j=int(np.argmax(np.linalg.norm(np.cross(a-a[0],a[i]-a[0]),axis=1))); ref["probes"]=a[[0,i,j]].tolist(); record(api,p,{"tracker_probes_saved":ref["key"]})
                T=t["transform_initial_world_to_current_world"]; return {"points":geo.transform(ref["probes"],T).tolist(),"T":T,"u":u,"spread":spread,"state":api.state(),"frame":t["frame_id"],"key":ref["key"],"source":"RGB-D rigid patch"}
            record(api,p,{"track_quality":{"inliers":t["inliers"],"u":u,"spread":spread}})
    if ref["manual"] and api.state()["frame_id"]==ref["frame"]:
        a=np.asarray(ref["probes"]); spread=np.linalg.svd(a-a.mean(axis=0),compute_uv=False)
        if spread[1]>.006:
            return {"points":ref["probes"],"T":np.eye(4).tolist(),"u":.003,"spread":float(spread[1]/math.sqrt(3)),"state":api.state(),"frame":ref["frame"],"key":ref["key"],"source":"new currently measured landmark reference"}
    if not manual or not ref["manual"]: return None
    r=ask(api,p,"Unknown or inadequate tracking. Independently locate CURRENT p0,p1,p2 corresponding to the saved physical definitions and reference geometry. Same-body identity does not imply unique landmark indices. Return body and correspondence; use ambiguous/unavailable rather than inventing correspondence. Request only those three points, from either current view.",{"body":["same_bowl","uncertain"],"correspondence":["unique","ambiguous","unavailable"]},{"reference":ref})
    if r is None or r["parameters"]["body"]!="same_bowl" or r["parameters"]["correspondence"]!="unique": return None
    b=np.asarray(pts(r,["p0","p1","p2"])); a=np.asarray(ref["probes"])
    if len(b)!=3: return None
    ac=a-a.mean(axis=0); bc=b-b.mean(axis=0); U,S,V=np.linalg.svd(ac.T@bc)
    if math.sqrt(max(0,float(S[1])))<.006: return None
    R=V.T@np.diag([1.,1.,float(np.linalg.det(V.T@U.T))])@U.T; T=np.eye(4); T[:3,:3]=R; T[:3,3]=b.mean(axis=0)-R@a.mean(axis=0); error=float(np.max(np.linalg.norm(geo.transform(a,T)-b,axis=1)))
    if error>.004: record(api,p,{"landmark_rigidity_error":error}); return None
    return {"points":b.tolist(),"T":T.tolist(),"u":.003+error,"spread":float(math.sqrt(max(0,float(S[1])))/math.sqrt(3)),"state":api.state(),"frame":r["frame_id"],"key":ref["key"],"source":"identified corresponding RGB-D landmarks"}
def move(api,p,target,calls=10,tol=.003):
    state=api.state(); reserve=2 if p["phase"] in ["released","verify_move"] else 28
    if state["budgets"]["jev_remaining"]<calls+reserve or state["budgets"]["native_steps_remaining"]<3*calls+3*reserve or state["budgets"]["wall_seconds_remaining"]<20: return None
    if np.linalg.norm(np.asarray(target)-geo.pad_position(state))>.59: return None
    r=api.drive(np.asarray(target).tolist(),p["plan"]["q"],"keep",questions(),features={"phase":p["phase"],"target_pad_world":np.asarray(target).tolist(),"geometry":{"rim_radius":p["plan"]["r"],"goal_xy":p["plan"]["goal"],"height_uncertainty":p["plan"]["height_u"]},"authorization":p["log"][-1],"effect_not_certified":True},tool_point="pad_center",max_calls=calls,translation_limit=.02,rotation_limit=.05,steps=3,position_tolerance=max(.0005,min(.006,tol)),rotation_tolerance=.04); record(api,p,{"motion":r["status"],"position_error":r["position_error_m"],"frame":r["frame_id"]}); return r
def jaw(api,p,command):
    for attempt in range(2):
        s=api.state()
        if s["budgets"]["jev_remaining"]<5 or s["budgets"]["native_steps_remaining"]<3 or s["budgets"]["wall_seconds_remaining"]<10: return False
        r=api.control(geo.pad_position(s).tolist(),s["tcp_quaternion_xyzw"],command,questions(),features={"phase":p["phase"],"jaw_request":command},tool_point="pad_center",translation_limit=.001,rotation_limit=.01,steps=3,position_tolerance=.003,rotation_tolerance=.04); record(api,p,{"jaw_requested":command,"choice":r["choices"]["gripper"],"receipt":r["status"],"acknowledged_steps":r["acknowledged_steps"]})
        if r["status"]=="stalled": return False
        if r["status"] in ["reached","moved"] and api.state()["last_gripper_command"]==command:
            now=api.state(); p["jaw_ack"]={"command":command,"frame":now["frame_id"],"qpos":now["gripper_qpos_m"]}; record(api,p,{"jaw_delivery_recorded":command}); return True
    return False
def retention(api,p,a,b):
    if a is None or b is None or a["key"]!=b["key"]: return "unknown"
    hand=geo.pad_position(b["state"])-geo.pad_position(a["state"]); d=float(np.linalg.norm(hand)); u=a["u"]+b["u"]; motion=np.mean(np.asarray(b["points"])-np.asarray(a["points"]),axis=0); progress=float(np.dot(motion,hand)/max(.000001,d)); e=float(geo.attachment_error(a["points"],b["points"],a["state"],b["state"])); record(api,p,{"hand_motion":d,"independent_object_progress":progress,"attachment_error":e,"combined_u":u})
    if d>.012 and progress-u>.45*d and e<.003+u: return "pass"
    if d>.018 and progress+u<.3*d: return "failed"
    if p.get("retained",False) and e<.003+u and d<.012: return "consistent"
    return "unknown"
def bind_envelope(api,p,s,g=None):
    if s is None: return False
    if g is None: g=outline(api,p,"Measure the current transported envelope; a visible rim arc is sufficient. No old vertex indices are required.")
    if g is None or g.get("relation","held")=="elsewhere" or abs(g["r"]-p["plan"]["r"])>g["u"]+p["plan"]["u"]+.004: return False
    c=np.asarray(g["c"]); b=c-[0,0,p["plan"]["h"]]; p["envelope"]={"key":s["key"],"points":geo.transform([c,b],np.linalg.inv(np.asarray(s["T"]))).tolist(),"r":p["plan"]["r"],"u_xy":g["u"],"u_z":(.002+p["plan"]["source_plane"]["rms_m"]) if g["frame"]==p["plan"]["frame"] else g["uz"]+p["plan"]["height_u"],"bind_u":s["u"],"bind_frame":g["frame"],"world_at_bind":[c.tolist(),b.tolist()]}; record(api,p,{"envelope_bound":s["key"],"measurement_frame":g["frame"]}); return True
def envelope(p,s):
    e=p.get("envelope")
    if s is None or e is None or s["key"]!=e["key"]: return None
    if s["frame"]==e["bind_frame"]: c,b=np.asarray(e["world_at_bind"])
    elif s["spread"]>3*s["u"]: c,b=geo.transform(e["points"],s["T"])
    else: return None
    h=max(.001,float(np.linalg.norm(c-b))); tilt=float(np.linalg.norm((c-b)[:2])/h); u=0. if s["frame"]==e["bind_frame"] else max(e["bind_u"],s["u"])*(1+e["r"]/max(.005,s["spread"])); return {"center":((c+b)/2).tolist(),"bottom":float(b[2]-e["r"]*tilt),"radius":e["r"]+.5*h*tilt,"u_xy":e["u_xy"]+u,"u_z":e["u_z"]+u,"tilt":tilt}
def margin(plan,center,radius):
    a=np.asarray(plan["deck"]); c=np.asarray(center)[:2]; edges=np.roll(a,-1,axis=0)-a; return float(np.min((edges[:,0]*(c[1]-a[:,1])-edges[:,1]*(c[0]-a[:,0])) / np.linalg.norm(edges,axis=1))-radius)
def local(api,p,purpose,context,reserve=3):
    f={"body":["same_bowl","uncertain"],"external":["observed_obstruction","none_observed","unknown"],"visibility":["locally_observed","robot_or_bowl_occlusion","unobserved_space"],"trial":["supported_local_trial","unsupported"]}
    if p["phase"] in ["closed","release_gate"]: f["relation"]=["rim_between_fingers","bowl_near_fingers","stove_support","small_gap_over_stove","elsewhere","unknown"]
    r=ask(api,p,purpose+" Return exactly the declared fields. external=observed_obstruction means an actual external obstacle intersects THIS proposed local sweep; request o0 at its highest relevant visible surface. none_observed is NOT certified clearance. visibility distinguishes robot/held-bowl occlusion from unobserved external space. supported_local_trial requires visible local geometry, own hand bounds and consistent short-horizon fixture geometry to justify this bounded action, not a complete later corridor. If no such local evidence exists use unsupported. Self-occlusion alone is not an external obstacle.",f,context,reserve)
    if r is not None and r["parameters"]["external"]=="observed_obstruction" and "o0" not in r["points"]:
        r=ask(api,p,"Replace the failed blocker measurement: request o0 on the highest relevant visible external obstacle surface from the other view. Return the same declared fields with the same meanings; do not change observed obstruction to clearance merely because measurement failed.",f,{"local_proposal":context,"measurement_errors":r["measurement_errors"]},reserve)
    return r
def initial(api,p):
    f,pixel=descriptors(); f.update(patch_fields()); f.update({"deck_camera":f["rim_camera"],"deck_pixels":{"type":"array","items":pixel,"maxItems":4}})
    for attempt in range(2):
        r=ask(api,p,"Task: put the bowl on stove table 1. Identify the patterned bowl and the stove platform with black burner, not the dining plate. Return all declared fields. Confirm upright round bowl, widest at its rim, resting on source tabletop. Request r0..r5 on spread visible rim lip surfaces and visible rim_pixels. Request s0,s1,s2 on source tabletop immediately around bowl; v0,v1,v2 on the white stove platform top; t0,t1,t2 on spread load-bearing upper burner surface. deck_pixels are the four visible stove platform top corners in deck_camera, not the burner. Select a textured bowl-interior patch, excluding fingers/background; p0,p1,p2 and definitions describe persistent physical motifs if uniquely identifiable, otherwise correspondence is ambiguous/unavailable. Use different points/view on retry, especially after depth-boundary failures.",f,{"attempt":attempt,"partial":p.get("partial")},5)
        if r is None: continue
        v=r["parameters"]; p["partial"]={"frame":r["frame_id"],"valid_points":{k:x["world_m"] for k,x in r["points"].items()}}; record(api,p,{"initial_frame":r["frame_id"]})
        if v["body"]!="same_bowl" or v["model"]!="upright_round_widest_rim" or v["relation"]!="source_support": continue
        g=rim(api,p,r); src=plane(pts(r,["s0","s1","s2"])); deck=plane(pts(r,["v0","v1","v2"])); top=plane(pts(r,["t0","t1","t2"]))
        if g is None or src is None or deck is None or top is None: continue
        poly=[]
        for pixel in v["deck_pixels"]:
            try: poly.append(api.plane_point(v["deck_camera"],pixel,deck["coefficients"])["world_m"][:2])
            except RuntimeError: record(api,p,{"gap":"deck boundary ray failed"})
        if len(poly)!=4: continue
        a=np.asarray(poly); xy=a.mean(axis=0); a=a[np.argsort(np.arctan2(a[:,1]-xy[1],a[:,0]-xy[0]))]; h=g["c"][2]-zplane(src,g["c"][:2]); state=api.state(); plan={"c":g["c"],"r":g["r"],"u":g["u"],"rim_z_u":g["uz"],"h":h,"height_u":g["uz"]+.002+src["rms_m"],"source_plane":src,"deck":a.tolist(),"goal":xy.tolist(),"top":top,"q":state["tcp_quaternion_xyzw"],"frame":r["frame_id"]}; centers=[xy]+[xy+.25*(x-xy) for x in a]; xy=max(centers,key=lambda x:margin(plan,x,g["r"])); plan["goal"]=xy.tolist(); m=margin(plan,xy,g["r"]); record(api,p,{"deck_nominal_margin":m,"rim_u":g["u"],"bowl_height":h})
        if h<=g["u"] or m<=0: continue
        p["plan"]=plan; p["partial"]={}; p["phase"]="approach"
        if not install_ref(api,p,r):
            s=new_ref(api,p)
        else: s=snapshot(api,p)
        if s is None: s=new_ref(api,p)
        if s is None: return False
        return bind_envelope(api,p,s,g)
    return False
def main(api):
    manifests=api.recall(); p=api.recall("bowl_v2")["value"] if any(x["key"]=="bowl_v2" for x in manifests) else {"phase":"survey","log":[],"tests":0,"legs":0,"retained":False}
    if p["phase"]=="done": p["phase"]="verify2"
    if p["phase"]=="survey" and not initial(api,p): return stop(api,p,"Initial geometry or reference unresolved after alternative measurements.")
    for cycle in range(128):
        phase=p["phase"]; plan=p["plan"]; state=api.state(); pad=geo.pad_position(state)
        if phase=="approach":
            if state["last_gripper_command"]!="open": return stop(api,p,"Unexpected jaw state before grasp; possible holding, will not reopen.")
            R=geo.rotation(plan["q"]); axis=R[:2,1]; axis=axis/np.linalg.norm(axis); extent=np.asarray(state["own_geometry"]["pad_extent_in_tool_m"]); half=.5*float(np.dot(np.abs(R[2,:]),extent)); lo=state["own_geometry"]["finger_low_offset_tool_m"]; hi=state["own_geometry"]["finger_high_offset_tool_m"]; offset=np.asarray(state["own_geometry"]["pad_center_in_tool_m"]); low=min(float((R@(np.asarray([x,y,z])-offset))[2]) for x in [lo[0],hi[0]] for y in [lo[1],hi[1]] for z in [lo[2],hi[2]]); candidates=[]
            for sign in [-1,1]:
                for dz in [-.25*half,0,.25*half]:
                    g=np.asarray(plan["c"])+np.array([sign*plan["r"]*axis[0],sign*plan["r"]*axis[1],dz])
                    if g[2]+low-zplane(plan["source_plane"],g[:2])>plan["height_u"]+.002 and half-abs(dz)>plan["rim_z_u"]:
                        candidates.append(g.tolist())
            record(api,p,{"pad_vertical_half_extent":half,"rim_z_u":plan["rim_z_u"],"finger_low_relative_pad":low,"bowl_height":plan["h"],"height_u":plan["height_u"],"feasible_grasp_candidates":len(candidates)})
            if not candidates: return stop(api,p,"No measured rim overlap/support clearance configuration; geometry-limited grasp.")
            f={"candidate":{"type":"integer","minimum":-1,"maximum":len(candidates)-1},"prior":["consistent_stationary","changed","unknown"],"decision":["supported","observed_obstruction","uncertain"]}; r=ask(api,p,"Return decision=supported, observed_obstruction, or uncertain separately from prior. Choose candidate for a single-rim pinch: one open finger enters the cavity and the other remains outside. candidate=-1 if neither side is justified; distinguish actual obstruction from uncertain clearance. Check the approach from current pad to above that candidate and vertical insertion, not the later transfer corridor. prior=consistent_stationary requires current partial rim geometry agreeing with the supplied circle and no possible previous bowl interaction. Request g0,g1 on currently visible rim portions; do not demand the full perimeter. If unknown, request a different visible arc.",f,{"candidates":candidates,"plan":plan,"own_geometry":state["own_geometry"],"opening_axis_world":R[:,1].tolist(),"qpos":state["gripper_qpos_m"]},5)
            if r is None: return stop(api,p,"Grasp approach evidence unavailable.")
            a=pts(r,["g0","g1"]); residual=max([abs(float(np.linalg.norm(np.asarray(x)[:2]-np.asarray(plan["c"])[:2]))-plan["r"])+abs(x[2]-plan["c"][2]) for x in a]+[0])
            if r["parameters"]["prior"]!="consistent_stationary" or r["parameters"]["decision"]=="uncertain" or len(a)<1 or residual>plan["u"]+.005:
                g=outline(api,p,"Revalidate source bowl after possible interaction; relation must identify source_support.",5)
                if g is None or g["relation"]!="source_support": return stop(api,p,"Source prior invalid and current source geometry unresolved.")
                plan["c"]=g["c"]; plan["r"]=g["r"]; plan["u"]=g["u"]; plan["rim_z_u"]=g["uz"]; plan["h"]=g["c"][2]-zplane(plan["source_plane"],g["c"][:2]); plan["height_u"]=g["uz"]+.002+plan["source_plane"]["rms_m"]; s=new_ref(api,p)
                if s is None or not bind_envelope(api,p,s,g): return stop(api,p,"Source reference replacement failed.")
                p["approach_retries"]=p.get("approach_retries",0)+1
                if p["approach_retries"]>1: return stop(api,p,"Source revalidation trial exhausted.")
                continue
            idx=r["parameters"]["candidate"]
